///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.reset
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.reset = function () {
    /* sdd-asis-lifecycle:begin fn_Reset — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.eduForm || { elements: [] });
    $c.util.getComponent('dma_RegisterReq').reset();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.print
 * @author Inswave
 * @date 2026. 09. 29
 * @param
