*/
scwin.print = function () {
    /* sdd-asis-lifecycle:begin fn_Print — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.popupPrint();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.register
 * @author Inswave
 * @date 2026. 09. 29
 * @param _submitYn
 * @returns
 * @hidden N
*/
scwin.register = async function (_submitYn) {
    /* sdd-asis-lifecycle:begin fn_Register — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.eduForm || { elements: [] });
    if ($c.util.getComponent('dma_RegisterReq').get('disclsEduApplSeq') === '73') {
        const count = (String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "count" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("count"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "count" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("count")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "count" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("count"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "count" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("count")))));
        if (parseInt(count) >= 250) {
            await $c.win.alert("교육수용인원이 초과되어 접수를 마감하였습니다.\n다음차수에 신청하여 주시기 바랍니다. 감사합니다.");
            return;
        }
    }
    if (!await scwin.chk()) {
        return;
    }
    await $c.win.alert("교육신청이 완료되었습니다.");
    frm.action = 'eduChrg.do';
    $c.util.getComponent('dma_RegisterReq').set('submitYn', _submitYn);
    $c.util.getComponent('dma_RegisterReq').set('method', 'registerChargeEducation');
    await scwin.tx_fn_Register();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.modify
 * @author Inswave
 * @date 2026. 09. 29
