*/
scwin.modify = async function (_submitYn) {
    /* sdd-asis-lifecycle:begin fn_Modify — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await scwin.chk()) {
        return;
    }
    const frm = (document.eduForm || { elements: [] });
    frm.action = 'eduChrg.do';
    $c.util.getComponent('dma_RegisterReq').set('submitYn', _submitYn);
    $c.util.getComponent('dma_RegisterReq').set('method', 'modifyChrgEducation');
    await scwin.tx_fn_Modify();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.deleteRegisterReq
 * @author Inswave
 * @date 2026. 09. 29
 * @param _disclsEduApplSeq _disclsChrgSeq _submitYn
 * @returns
 * @hidden N
*/
scwin.deleteRegisterReq = async function (_disclsEduApplSeq, _disclsChrgSeq, _submitYn) {
    /* sdd-asis-lifecycle:begin fn_Delete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (await $c.win.confirm("삭제 하시겠습니까?") === true) {
        const eduForm = (document.eduForm || { elements: [] });
        $c.util.getComponent('dma_RegisterReq').set('disclsEduApplSeq', _disclsEduApplSeq);
        $c.util.getComponent('dma_RegisterReq').set('disclsChrgSeq', _disclsChrgSeq);
        $c.util.getComponent('dma_RegisterReq').set('submitYn', _submitYn);
        scwin.form_eduForm.action = 'eduChrg.do';
        $c.util.getComponent('dma_RegisterReq').set('method', 'removeChargeEducation');
        await scwin.tx_fn_Delete();
    } else {
        return;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.chk
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.chk = async function () {
    /* sdd-asis-lifecycle:begin fn_Chk — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.eduForm || { elements: [] });
    if (($c.util.getComponent('ipt_chrgNm').getValue() == null ? '' : String($c.util.getComponent('ipt_chrgNm').getValue())) === '' || $c.util.getComponent('ipt_chrgNm').getValue().indexOf(" ") === "") {
        await $c.win.alert("성명을 입력해 주세요");
        $c.util.getComponent("ipt_chrgNm").focus();
        return false;
    }
    if (($c.util.getComponent('ipt_depNm').getValue() == null ? '' : String($c.util.getComponent('ipt_depNm').getValue())) === '' || $c.util.getComponent('ipt_depNm').getValue().indexOf(" ") === "") {
        await $c.win.alert("소속 부서를 입력해 주세요");
        $c.util.getComponent("ipt_depNm").focus();
        return false;
    }
    if (($c.util.getComponent('ipt_jobtitlNm').getValue() == null ? '' : String($c.util.getComponent('ipt_jobtitlNm').getValue())) === '' || $c.util.getComponent('ipt_jobtitlNm').getValue().indexOf(" ") === "") {
        await $c.win.alert("직위를 입력해 주세요");
        $c.util.getComponent("ipt_jobtitlNm").focus();
        return false;
    }
    if (($c.util.getComponent('ipt_cellphoneNo').getValue() == null ? '' : String($c.util.getComponent('ipt_cellphoneNo').getValue())) === '' || $c.util.getComponent('ipt_cellphoneNo').getValue().indexOf(" ") === "") {
        await $c.win.alert("휴대폰 번호를 입력해 주세요");
        $c.util.getComponent("ipt_cellphoneNo").focus();
        return false;
    }
    if (($c.util.getComponent('ipt_email').getValue() == null ? '' : String($c.util.getComponent('ipt_email').getValue())) === '' || $c.util.getComponent('ipt_email').getValue().indexOf(" ") === "") {
        await $c.win.alert("이메일을 입력해 주세요");
        $c.util.getComponent("ipt_email").focus();
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};
